"""Write mathion/branding_defaults.py from branding-defaults/ (Branding D6).

Run from backend/ after changing the default icon:
    .venv/bin/python scripts/gen_branding_defaults.py
"""
import base64
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
FILES = (("ICON_SVG", "icon.svg"), ("ICON_32_PNG", "icon-32.png"), ("ICON_180_PNG", "icon-180.png"))


def main() -> None:
    lines = [
        '"""The default tab icon (Branding D6). Generated by scripts/gen_branding_defaults.py',
        'from branding-defaults/; don\'t edit by hand."""',
        "import base64",
        "",
    ]
    for name, file in FILES:
        data = base64.b64encode((ROOT / "branding-defaults" / file).read_bytes()).decode()
        chunks = [data[i:i + 96] for i in range(0, len(data), 96)]
        lines.append(f"{name} = base64.b64decode(")
        lines += [f'    "{c}"' for c in chunks]
        lines.append(")")
    (ROOT / "mathion" / "branding_defaults.py").write_text("\n".join(lines) + "\n")


if __name__ == "__main__":
    main()
